const {spawn}=require('node:child_process'); const fs=require('node:fs'); const os=require('node:os'); const path=require('node:path');
const profile=fs.mkdtempSync(path.join(os.tmpdir(),'monday-cdp-'));
const chrome=spawn('/usr/bin/google-chrome',['--headless=new','--no-sandbox','--disable-gpu','--remote-debugging-port=0',`--user-data-dir=${profile}`,'about:blank'],{stdio:['ignore','ignore','pipe'],detached:true});
chrome.unref();
let seq=0, ws=null, sessionId=null, pending=new Map();
function rpc(method,params={},session=null){return new Promise((resolve,reject)=>{const id=++seq; pending.set(id,{resolve,reject}); ws.send(JSON.stringify({id,method,params,...(session?{sessionId:session}:{})})); setTimeout(()=>{if(pending.has(id)){pending.delete(id);reject(new Error('cdp timeout '+method));}},5000);});}
function finish(out,code=0){try{fs.writeFileSync('browser-primitive.json',JSON.stringify(out));}catch{} try{ws?.close();}catch{} try{process.kill(-chrome.pid,'SIGKILL');}catch{} process.exit(code);}
let stderr='';
chrome.stderr.on('data',chunk=>{stderr+=chunk.toString(); const m=stderr.match(/DevTools listening on (ws:\/\/[^\s]+)/); if(m&&!ws){ws=new WebSocket(m[1]); ws.onmessage=e=>{const msg=JSON.parse(e.data); if(msg.id&&pending.has(msg.id)){const p=pending.get(msg.id);pending.delete(msg.id); msg.error?p.reject(new Error(msg.error.message)):p.resolve(msg.result);}}; ws.onopen=async()=>{try{const t=await rpc('Target.createTarget',{url:'data:text/html,<title>Monday</title><body>browser-ok</body>'}); const a=await rpc('Target.attachToTarget',{targetId:t.targetId,flatten:true}); sessionId=a.sessionId; await new Promise(r=>setTimeout(r,250)); const v=await rpc('Runtime.evaluate',{expression:'document.body.innerText',returnByValue:true},sessionId); finish({cdp:true,webSocketType:typeof WebSocket,text:v.result.value,browserWs:m[1].replace(/\/[^/]+$/,'/<id>')},0);}catch(err){finish({cdp:false,error:String(err),stderrTail:stderr.slice(-1200)},0);}};}});
setTimeout(()=>finish({cdp:false,error:'devtools websocket not found',stderrTail:stderr.slice(-1200)},0),10000);
